 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in markers:
        # A five-cell-wide cap, vertical sides, and a bottom band.
        top, bottom = r - 2, r + 2
        left, right = c - 2, c + 2
        if top >= 0 and bottom < h and left >= 0 and right < w:
            for x in range(left, right + 1):
                out[top][x] = 5
                out[bottom][x] = 8
            for y in range(r - 1, r + 2):
                out[y][left] = 2
                out[y][right] = 2
            out[r][c] = 3
            # Extend the baseline to both grid edges in color 2.
            for x in range(w):
                if x < left or x > right:
                    out[bottom][x] = 2
    return out
